exercise.starterCode:
interface Hero {
  name: string;
  level: number;
}

function intro(h: Hero): string {
  // 返回 'V(66)'
  return '';
}

exercise.solution:
interface Hero {
  name: string;
  level: number;
}

function intro(h: Hero): string {
  return h.name + '(' + h.level + ')';
}

