enum Rank {
  Rookie,
  Hacker,
  Legend
}

function rankName(level: Rank): string {
  // Rookie→'rookie'，Hacker→'hacker'，Legend→'legend'
  return '';
}

exercise.solution:
enum Rank {
  Rookie,
  Hacker,
  Legend
}

function rankName(level: Rank): string {
  if (level === Rank.Rookie) { return 'rookie'; }
  if (level === Rank.Hacker) { return 'hacker'; }
  return 'legend';
}
